package net.minecraftforge.common.ticket;

import com.google.common.base.Preconditions;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.function.Consumer;

/**
 * Common class for a simple ticket based system.
 * @param <T> The type that will be used to check if your ticket matches
 */
public abstract class SimpleTicket<T>
{
    @Nullable
    private ITicketManager<T> masterManager;
    private ITicketManager<T>[] dummyManagers;
    protected boolean isValid = false;

    /**
     * Internal method that sets the collection from the managing system.
     * <br>
     * Should <b>not</b> be called if you just want to register a ticket to a system like the {@link net.minecraftforge.common.FarmlandWaterManager}
     */
    @SafeVarargs
    public final void setManager(@NotNull ITicketManager<T> masterManager, @NotNull ITicketManager<T>... dummyManagers)
    {
        Preconditions.checkState(this.masterManager == null, "Ticket is already registered to a managing system");
        this.masterManager = masterManager;
        this.dummyManagers = dummyManagers;
    }

    /**
     * Checks if your ticket is still registered in the system.
     */
    public boolean isValid()
    {
        return isValid;
    }

    /**
     * Removes the ticket from the managing system.
     * After this call, any calls to {@link #isValid()} should return false unless it is registered again using {@link #validate()}
     */
    public void invalidate()
    {
        if (this.isValid())
        {
            forEachManager(ticketManager -> ticketManager.remove(this));
        }
        this.isValid = false;
    }

    /**
     * Called by the managing system when a ticket wishes to unload all of it's tickets, e.g. on chunk unload
     * <br>The ticket must not remove itself from the manager that is calling the unload!
     * The ticket must ensure that it removes itself from all of it's dummies when returning true
     * @param unloadingManager The manager that is unloading this ticket
     * @return true if this ticket can be removed, false if not.
     */
    public boolean unload(ITicketManager<T> unloadingManager)
    {
        if (unloadingManager == masterManager)
        {
            for (ITicketManager<T> manager : dummyManagers)
            {
                manager.remove(this); //remove ourself from all dummies
            }
            this.isValid = false; //and mark us as invalid
            return true;
        }
        return false;
    }

    /**
     * Re-adds your ticket to the system.
     */
    public void validate()
    {
        if (!this.isValid())
        {
            forEachManager(ticketManager -> ticketManager.add(this));
        }
        this.isValid = true;
    }

    public abstract boolean matches(T toMatch);

    //Helper methods for custom tickets below

    protected final void forEachManager(Consumer<ITicketManager<T>> consumer)
    {
        Preconditions.checkState(this.masterManager != null, "Ticket is not registered to a managing system");
        consumer.accept(masterManager);
        for (ITicketManager<T> manager : dummyManagers)
        {
            consumer.accept(manager);
        }
    }

    protected final ITicketManager<T> getMasterManager()
    {
        return masterManager;
    }

    protected final ITicketManager<T>[] getDummyManagers()
    {
        return dummyManagers;
    }
}

public static boolean onFarmlandTrample(Level level, BlockPos pos, BlockState state, float fallDistance, Entity entity)
{
    if (entity.canTrample(state, pos, fallDistance))
    {
        BlockEvent.FarmlandTrampleEvent event = new BlockEvent.FarmlandTrampleEvent(level, pos, state, fallDistance, entity);
        MinecraftForge.EVENT_BUS.post(event);
        return !event.isCanceled();
    }
    return false;
}

public boolean canTrample(BlockState state, BlockPos pos, float fallDistance) {
   return level.random.nextFloat() < fallDistance - 0.5F
       && this instanceof LivingEntity
       && (this instanceof Player || net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(level, this))
       && this.getBbWidth() * this.getBbWidth() * this.getBbHeight() > 0.512F;
}

/**
 * Fired when when farmland gets trampled
 * This event is {@link Cancelable}
 */
@Cancelable
public static class FarmlandTrampleEvent extends BlockEvent
{

    private final Entity entity;
    private final float fallDistance;

    public FarmlandTrampleEvent(Level level, BlockPos pos, BlockState state, float fallDistance, Entity entity)
    {
        super(level, pos, state);
        this.entity = entity;
        this.fallDistance = fallDistance;
    }

    public Entity getEntity() {
        return entity;
    }

    public float getFallDistance() {
        return fallDistance;
    }

}

public static BlockState pushEntitiesUp(BlockState p_49898_, BlockState p_49899_, LevelAccessor p_238252_, BlockPos p_49901_) {
   VoxelShape voxelshape = Shapes.joinUnoptimized(p_49898_.getCollisionShape(p_238252_, p_49901_), p_49899_.getCollisionShape(p_238252_, p_49901_), BooleanOp.ONLY_SECOND).move((double)p_49901_.getX(), (double)p_49901_.getY(), (double)p_49901_.getZ());
   if (voxelshape.isEmpty()) {
      return p_49899_;
   } else {
      for(Entity entity : p_238252_.getEntities((Entity)null, voxelshape.bounds())) {
         double d0 = Shapes.collide(Direction.Axis.Y, entity.getBoundingBox().move(0.0D, 1.0D, 0.0D), List.of(voxelshape), -1.0D);
         entity.teleportRelative(0.0D, 1.0D + d0, 0.0D);
      }

      return p_49899_;
   }
}

public boolean contains(Vec3 p_82391_) {
   return this.contains(p_82391_.x, p_82391_.y, p_82391_.z);
}

public boolean contains(double p_82394_, double p_82395_, double p_82396_) {
   return p_82394_ >= this.minX && p_82394_ < this.maxX && p_82395_ >= this.minY && p_82395_ < this.maxY && p_82396_ >= this.minZ && p_82396_ < this.maxZ;
}

public void fallOn(Level p_152426_, BlockState p_152427_, BlockPos p_152428_, Entity p_152429_, float p_152430_) {
   p_152429_.causeFallDamage(p_152430_, 1.0F, p_152429_.damageSources().fall());
}

public static boolean getMobGriefingEvent(Level level, @Nullable Entity entity)
{
    if (entity == null)
        return level.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING);

    EntityMobGriefingEvent event = new EntityMobGriefingEvent(entity);
    MinecraftForge.EVENT_BUS.post(event);

    Result result = event.getResult();
    return result == Result.DEFAULT ? level.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING) : result == Result.ALLOW;
}

@SubscribeEvent
public void onChunkUnload(ChunkEvent.Unload event)
{
    if (!event.getLevel().isClientSide())
        FarmlandWaterManager.removeTickets(event.getChunk());
}

